import { createFileRoute, useRouter } from '@tanstack/react-router'
import { createServerFn } from '@tanstack/react-start'
import { getCount, incrementCount } from '../db'

export const getCountServerFn = createServerFn({ method: 'GET' }).handler(async () => {
  return getCount()
})

export const incrementCountServerFn = createServerFn({ method: 'POST' }).handler(async () => {
  return incrementCount()
})

export const Route = createFileRoute('/')({
  loader: async () => {
    const count = await getCountServerFn()
    return { count }
  },
  component: Home,
})

function Home() {
